(function(){"use strict";chrome.runtime.onInstalled.addListener(e=>{e.reason==="install"&&chrome.storage.sync.set({enabled:!0},()=>{console.log("[mapshort] 初回インストール: デフォルト設定を保存しました")})}),chrome.runtime.onMessage.addListener((e,a,t)=>{if(e.type==="FETCH_YOUTUBE_SEARCH"){const o=typeof e.query=="string"?e.query:"";if(!o){t({ok:!1,error:"検索語が空です"});return}const u=`https://www.youtube.com/results?search_query=${encodeURIComponent(o)}`;return fetch(u,{headers:{Accept:"text/html","Accept-Language":"ja"}}).then(async r=>{if(!r.ok){t({ok:!1,error:`YouTube検索ページを取得できませんでした: ${r.status}`});return}t({ok:!0,html:await r.text()})}).catch(r=>{t({ok:!1,error:`YouTube検索ページの取得に失敗しました: ${r instanceof Error?r.message:"network error"}`})}),!0}return e.type==="CLEAR_CACHE"?(chrome.tabs.query({url:["*://www.google.com/maps/*","*://maps.google.com/*"]},o=>{o.forEach(u=>{u.id!=null&&chrome.tabs.sendMessage(u.id,{type:"CLEAR_CACHE"}).catch(()=>{})}),t({ok:!0})}),!0):!1})})();
